local config = {
  ui_story_30110401_1_dialog_content = "<color=#e8d9bb>... 1, 2, 3, 4...</color>",
  ui_story_30110401_2_dialog_content = "<color=#e8d9bb>Omong-omong, sepertinya aku melupakan sesuatu yang penting...</color>",
  ui_story_30110401_3_dialog_content = "Kenapa kamu melamun? Kamu dengar pertanyaanku?",
  ui_story_30110401_4_dialog_content = "Kalau begitu, aku akan mengulanginya: Tolong jelaskan bagaimana kamu tidak bisa tidur nyenyak.",
  ui_story_30110401_5_option_content = "Maaf, Kapten. Kamu membuatku takut.",
  ui_story_30110401_6_dialog_content = "Aku tidak bermaksud apa-apa. Silakan coba untuk terbiasa dengan ini.",
  ui_story_30110401_7_dialog_content = "Aku memintamu untuk menjelaskannya karena sulit bagiku untuk mengambil tindakan apa pun sebelum tahu lebih banyak tentang situasimu.",
  ui_story_30110401_8_option_content = "Maaf. Aku keasyikan melamun.",
  ui_story_30110401_9_dialog_content = "Mungkin aku kurang jelas. Aku ingin agar kamu bisa memberi penjelasan singkat kepadaku tentang situasimu.",
  ui_story_30110401_10_dialog_content = "Begitu sudah paham, aku akan bisa memilih solusi yang lebih tepat.",
  ui_story_30110401_11_dialog_content = "Yah, aku kesulitan tidur dan bangun, merasa pusing dan lelah sepanjang waktu.",
  ui_story_30110401_12_dialog_content = "Tapi kenapa kamu peduli tentang hal ini, Kapten?",
  ui_story_30110401_13_dialog_content = "... Dan sepertinya kau berniat membantuku mengatasinya?",
  ui_story_30110401_14_dialog_content = "Pertama, ini bukan satu-satunya hal yang aku minta agar kamu tangani. Aku punya pertimbanganku.",
  ui_story_30110401_15_dialog_content = "Lakukan saja seperti yang kukatakan. Tak usah khawatir.",
  ui_story_30110401_16_dialog_content = "Kedua, para prajurit di legiun yang kulatih sering mengalami masalah yang serupa denganmu.",
  ui_story_30110401_17_dialog_content = "Karena aku berpengalaman mengurus mereka, akan mudah untuk membantumu.",
  ui_story_30110401_18_option_content = "Kedengarannya kamu baru saja menyingkirkan prajurit yang bermasalah...",
  ui_story_30110401_19_dialog_content = "Tidak, aku menyingkirkan masalah tidur mereka, tentu saja.",
  ui_story_30110401_20_dialog_content = "Jangan khawatir. Hanya 10 persen dari yang kusingkirkan ini adalah prajurit yang bermasalah.",
  ui_story_30110401_21_dialog_content = "Aku tidak termasuk 10 persen itu, 'kan...",
  ui_story_30110401_22_option_content = "Menakjubkan. Jadi, lakukan saja seperti yang kamu katakan, 'kan?",
  ui_story_30110401_23_dialog_content = "Tentu saja tidak. Aku tahu dari pengalaman bahwa metode ini dapat secara efektif mengeluarkan potensi tubuh manusia.",
  ui_story_30110401_24_dialog_content = "Ini akan meningkatkan kesehatanmu. Aku janji kamu akan tidur sangat nyenyak.",
  ui_story_30110401_25_dialog_content = "Hmm? Ada yang terdengar janggal.",
  ui_story_30110401_26_dialog_content = "Kamu lihat pilar di sebelah sana?",
  ui_story_30110401_27_dialog_content = "Tatap pilar itu, dan jangan hilang fokus. Mulailah bergerak begitu aku memberi perintah. Jangan ragu.",
  ui_story_30110401_28_dialog_content = "100 squat! Sekarang!",
  ui_story_30110401_29_option_content = "???",
  ui_story_30110401_30_dialog_content = "Aku sudah bilang, jangan ragu. Lakukan 50 squat lagi! Sekarang!",
  ui_story_30110401_31_option_content = "Ya, Kapten!",
  ui_story_30110401_32_dialog_content = "Reaksi cepat. Bagus. 50 lagi!",
  ui_story_30110401_33_dialog_content = "Lari 20 putaran mengelilingi Jembatan. Mulai!",
  ui_story_30110401_34_dialog_content = "Deep squat! Shuttle jump! Lagi! Belum selesai! Teruskan!",
  ui_story_30110401_35_option_content = "Aku tak sanggup lagi, Kapten. Aku boleh istirahat?",
  ui_story_30110401_36_dialog_content = "Kegigihan adalah kemenangan. Karena aku sudah berjanji untuk lebih mengawasimu, kamu harus menyelesaikan latihanmu.",
  ui_story_30110401_37_option_content = "Kurang berapa lagi, Kapten?",
  ui_story_30110401_38_dialog_content = "Panah yang sudah dilepaskan tidak bisa kembali.",
  ui_story_30110401_39_dialog_content = "Jangan berpikir tentang berapa lama lagi, pikirkan apa yang akan kamu peroleh dari ini!",
  ui_story_30110401_40_dialog_content = "<color=#e8d9bb>Entah berapa lama Officer Sharona ingin ini terus berlanjut, tapi otakku sudah akan mati...</color>",
  ui_story_30110401_41_dialog_content = "<color=#e8d9bb>1, 2, 3, 4...!</color>",
  ui_story_30110401_42_dialog_content = "Hah? Ini 'kan...",
  ui_story_30110401_43_dialog_content = "Pertahankan temponya! Ayo, teriakkan bersamaku! Biarkan aku mendengarmu! 1, 2, 3, 4!",
  ui_story_30110401_44_option_content = "Ini memalukan... Tunggu sebentar, aku jadi ingat!",
  ui_story_30110401_45_dialog_content = "Aku bersikeras untuk melakukan latihan pagi setiap hari, begitu banyak orang pasti ingat itu. Ternyata, sudah banyak yang menunjukkan ketertarikannya untuk bergabung.",
  ui_story_30110401_46_option_content = "Jadi, kamulah yang membangunkanku setiap pagi!",
  ui_story_30110401_47_dialog_content = "Kenapa? Aku memang menerima beberapa keluhan, itulah sebabnya aku mengubah lokasi latihan ke Bridge, yang menurutku cukup jauh dari area tempat tinggal.",
  ui_story_30110401_48_dialog_content = "Kamarku adalah yang paling dekat dengan Jembatan. Mungkin itu sebabnya aku selalu mendengarmu dalam tidurku setiap pagi.",
  ui_story_30110401_49_dialog_content = "Pantas saja aku selalu merasa lelah saat bangun tidur...",
  ui_story_30110401_50_dialog_content = "Yah, meskipun terlihat enggan, kamu tetap menyelesaikan sesi latihanku.",
  ui_story_30110401_51_dialog_content = "Dan kamu berhasil menyelesaikannya dengan baik. Sebenarnya kamu berbakat.",
  ui_story_30110401_52_dialog_content = "Karena sering kali tidak bisa berpartisipasi dalam pertempuran, kamu tidak punya banyak kesempatan untuk meningkatkan dirimu. Latihan menawarkan kesempatan terbaik untuk itu.",
  ui_story_30110401_53_dialog_content = "Selain itu, penilaian tempurmu harusnya tidak berada di level terendah.",
  ui_story_30110401_54_option_content = "Kamu begitu tangguh, dan baru saja mengubah topiknya!",
  ui_story_30110401_55_dialog_content = "Bukan masalah. Aku memang berjanji untuk mengatasi masalahmu.",
  ui_story_30110401_56_dialog_content = "Aku bukan bersikap keras, melainkan peduli.",
  ui_story_30110401_57_option_content = "Kamu begitu tegas, dan tiba-tiba memintaku untuk menjadi lebih kuat?",
  ui_story_30110401_58_dialog_content = "Tentu saja. Kami tidak hanya berharap agar kamu menjadi lebih kuat, tapi juga berharap agar kamu mendapatkan lebih banyak perhatian.",
  ui_story_30110401_59_dialog_content = "Waktunya istirahat! Kamu sudah berhenti, tapi aku akan mengizinkannya! Bukan masalah!",
  ui_story_30110401_60_dialog_content = "Kamu harus tahu bahwa aku sangat mengerti efek dari latihan ini.",
  ui_story_30110401_61_dialog_content = "Latihan harian inilah yang membantuku menjadi jenderal. Aku tak akan berbohong kepadamu tentang ini, ya, 'kan?",
  ui_story_30110401_62_dialog_content = "Menurutku karena kamu spesial, Kapten. Biasanya, tidak ada yang dipromosikan menjadi jenderal hanya dengan berlatih saja.",
  ui_story_30110401_63_dialog_content = "Keteguhan yang kuat diperlukan untuk menjadi Legion Commander. Ini juga adalah dasar di mana Power Puzzle Illumina diselesaikan secara bertahap.",
  ui_story_30110401_64_dialog_content = "Dan jangan lupa, kamu juga spesial... Grand Marshal Illumina tidak pernah salah menilai orang.",
  ui_story_30110401_65_dialog_content = "Meskipun begitu, aku masih ada di sini untuk mengatasi masalahmu.",
  ui_story_30110401_66_dialog_content = "Berlatih dengan cukup bisa meningkatkan kualitas tidurmu. Jadi, tetap semangat, wargaku!",
  ui_story_30110401_67_option_content = "Tunggu, sepertinya aku mendengar sesuatu yang penting...",
  ui_story_30110401_68_dialog_content = "Jangan khawatir. Kamu akan mengerti semuanya ketika waktunya tiba.",
  ui_story_30110401_69_dialog_content = "Selain itu, kamu tidak akan kesulitan bangun besok.",
  ui_story_30110401_70_option_content = "Lupakan tentang tidur. Aku mau pingsan...",
  ui_story_30110401_71_dialog_content = "Aku bisa membantu jika kamu membutuhkannya sekarang.",
  ui_story_30110401_72_dialog_content = "Aku akan memberi tahu semuanya bahwa kamu sudah pergi untuk istirahat hari ini.",
  ui_story_30110401_73_dialog_content = "Mulai besok pagi, aku sendiri yang akan menyeretmu bangun dari tempat tidur untuk latihan!",
  ui_story_30110401_74_dialog_content = "Sekarang, mari kita selesaikan sisa sesi ini!",
  ui_story_30110401_75_dialog_content = "Masih ada yang bisa diperbaiki lagi dalam penilaianmu...",
  ui_story_30110601_1_dialog_content = "Kembali di Gannon City, ya...",
  ui_story_30110601_2_dialog_content = "Vice membuat laporan rutinnya... dan prosesnya bisa memakan waktu lama.",
  ui_story_30110601_3_dialog_content = "Mari kita lihat... Mungkin aku bisa kembali ke Colossus dan tidur beberapa menit lagi...",
  ui_story_30110601_4_dialog_content = "Ini kali ketiga kamu menolakku, kawan!",
  ui_story_30110601_5_dialog_content = "Benar sekali.",
  ui_story_30110601_6_dialog_content = "Pesawat umum saja tidak memungkinkan bagiku, apalagi kereta yang menggetarkan bumi milikmu itu...",
  ui_story_30110601_7_dialog_content = "Hmm? Itu Sharona dan Charon...",
  ui_story_30110601_8_dialog_content = "Sharona tampak sedikit berbeda ketika dia tidak sedang bertempur...",
  ui_story_30110601_9_dialog_content = "Aku harus menyapa.",
  ui_story_30110601_10_dialog_content = "Ah! Rupanya kamu, Caelestite! Temanku tersayang!",
  ui_story_30110601_11_dialog_content = "Mumpung kamu di sini, maukah kamu membantuku membujuk Commander tersayang untuk menyetujui cara perjalanan?",
  ui_story_30110601_12_dialog_content = "Ada atau tidaknya Caelestite di sini tidak ada bedanya, Charon.",
  ui_story_30110601_13_dialog_content = "Jawabanku tetap sama: keretamu itu tidak tertahankan untuk dinaiki.",
  ui_story_30110601_14_dialog_content = "Aku akan mencari cara untuk memperbaiki pesawatku...",
  ui_story_30110601_15_dialog_content = "(Tampaknya Sharona ingin pergi ke suatu tempat, dan ingin bepergian sendirian...)",
  ui_story_30110601_16_dialog_content = "(Pesawatnya rusak, dan dia tidak bisa menggunakan angkutan umum atau Other End...)",
  ui_story_30110601_17_dialog_content = "Eh, Commander Sharona...?",
  ui_story_30110601_18_dialog_content = "M-mungkin aku bisa... membantu?",
  ui_story_30110601_19_dialog_content = "Kamu tidak punya hal lain untuk dilakukan, Caelestite?",
  ui_story_30110601_20_dialog_content = "Atau apakah kamu benar-benar mengira Colossus kurang menarik perhatian daripada kereta Charon?",
  ui_story_30110601_21_dialog_content = "Eh... S-semacam itulah?",
  ui_story_30110601_22_dialog_content = "Setidaknya Soroz tidak memutar musik aneh saat bepergian.",
  ui_story_30110601_23_dialog_content = "…Benar juga.",
  ui_story_30110601_24_dialog_content = "Apa pun itu, ini adalah masalahku sendiri.",
  ui_story_30110601_25_dialog_content = "Namun, kamu benar-benar sedang kesulitan, 'kan?",
  ui_story_30110601_26_dialog_content = "Janji, aku tidak akan mencampuri urusan pribadimu... Itu urusanmu, bukan urusanku.",
  ui_story_30110601_27_dialog_content = "Tapi, aku benar-benar yakin bisa membantu kamu dengan dilema transportasimu.",
  ui_story_30110601_28_dialog_content = "Tentu saja kamu berhak menolak...",
  ui_story_30110601_29_dialog_content = "Pada akhirnya, ini terserah kamu. Aku hanya ingin memberikan pilihan lain untukmu.",
  ui_story_30110601_30_dialog_content = "...Baiklah.",
  ui_story_30110601_31_dialog_content = "Kalau begitu, mari kita bergerak.",
  ui_story_30110601_32_dialog_content = "S-sudah?! Cepat sekali!",
  ui_story_30110601_33_dialog_content = "Apa? Kamu urung melakukannya?",
  ui_story_30110601_34_dialog_content = "Tidak!",
  ui_story_30110601_35_dialog_content = "Kalau begitu, ayo.",
  ui_story_30110601_36_dialog_content = "T-tunggu aku...!",
  ui_story_30110601_37_dialog_content = "Sekarang jika aku pikirkan... Setiap tahun, tanpa pernah absen, Sharona berpakaian seperti ini dan pergi ke lokasi yang tidak diketahui.",
  ui_story_30110601_38_dialog_content = "Aku ingin tahu apa artinya... Keilahian apa yang bisa membimbing tindakan Lastborn of Laden?",
  ui_story_30110601_39_dialog_content = "...Hmm? Ke mana perginya Caelestite?",
  ui_story_30110601_40_dialog_content = "Ho-ho! Aku sangat menantikan pertunjukan hari ini!",
  ui_story_30110601_41_dialog_content = "<color=#e8d9bb>Di luar Umbraton, di sebuah lembah terpencil...</color>",
  ui_story_30110601_42_dialog_content = "Kita hampir sampai di lokasi yang kamu minta.",
  ui_story_30110601_43_dialog_content = "Kamu yakin ini tempat yang tepat, Sharona?",
  ui_story_30110601_44_dialog_content = "Tempat ini tampak benar-benar gersang...",
  ui_story_30110601_45_dialog_content = "Ini adalah tempat yang tepat.",
  ui_story_30110601_46_dialog_content = "Hah... Kalau dipikir-pikir, kelihatannya tidak asing.",
  ui_story_30110601_47_dialog_content = "Ini... Ini tepat di bawah Lumopolis, 'kan?",
  ui_story_30110601_48_dialog_content = "Ya.",
  ui_story_30110601_49_dialog_content = "Area tersembunyi ini juga bisa digunakan untuk kabur dari serbuan Eclipsite.",
  ui_story_30110601_50_dialog_content = "Ya... Sepertinya ini tempat yang bagus. Benar-benar sepi dan tenang...",
  ui_story_30110601_51_dialog_content = "Seringnya...",
  ui_story_30110601_52_dialog_content = "Sebaiknya kamu tetap berada di sebelahku, Caelestite.",
  ui_story_30110601_53_dialog_content = "Akulah satu-satunya yang bisa menjamin keselamatanmu di tempat ini.",
  ui_story_30110601_54_dialog_content = "Tetap berada di atas Colossus itu pilihan lain, tetapi belum tentu yang terbaik.",
  ui_story_30110601_55_dialog_content = "Jika ada yang melihatnya, kemungkinan besar mereka akan menyerang...",
  ui_story_30110601_56_dialog_content = "Jadi, tetaplah sedekat mungkin denganku.",
  ui_story_30110601_57_dialog_content = "Saat kita tiba di tujuan, tunggu aku di luar.",
  ui_story_30110601_58_dialog_content = "Aku... Aku takkan lama, janji.",
  ui_story_30110601_59_dialog_content = "Jika kamu melihat tanda-tanda bahaya. Panggillah aku, dan aku akan segera keluar.",
  ui_story_30110601_60_dialog_content = "Selebihnya bukan urusanmu.",
  ui_story_30110601_61_dialog_content = "Itulah rencana untuk perjalanan ini. Ada pertanyaan, Caelestite?",
  ui_story_30110601_62_dialog_content = "...T-tidak, aku paham!",
  ui_story_30110601_63_dialog_content = "Bagus. Sekarang... Ayo pergi.",
  ui_story_30110601_64_dialog_content = "Baiklah... Kita sudah sampai.",
  ui_story_30110601_65_dialog_content = "Aku masuk dulu.",
  ui_story_30110601_66_dialog_content = "Dia pergi begitu cepat...",
  ui_story_30110601_67_dialog_content = "Sekarang aku sendirian, tempat ini terasa sedikit menyeramkan.",
  ui_story_30110601_68_dialog_content = "Dingin...",
  ui_story_30110601_69_dialog_content = "Vegetasi di sini sangat lebat.",
  ui_story_30110601_70_dialog_content = "Di sini sepi... Terlalu sepi. Ini hampir tak tertahankan...",
  ui_story_30110601_71_dialog_content = "Kurasa aku akan berdiri lebih dekat ke pintu masuk...",
  ui_story_30110601_72_dialog_content = "Graaagh!",
  ui_story_30110601_73_dialog_content = "Jadi, mereka menemukan tempat ini juga...",
  ui_story_30110601_74_dialog_content = "Graaaagh!!!",
  ui_story_30110601_75_dialog_content = "Beraninya kamu mengamuk di sini!",
  ui_story_30110601_76_dialog_content = "Gawat, apa itu... bau Eclipsite?!",
  ui_story_30110601_77_dialog_content = "Ada suara pertarungan yang datang dari dalam...",
  ui_story_30110601_78_dialog_content = "Sharona di sana sendirian! Aku harus pergi membantunya!",
  ui_story_30110601_79_dialog_content = "Tempat ini... adalah kuburan?",
  ui_story_30110601_80_dialog_content = "Saat ini anehnya sepi... Apakah pertempuran sudah berakhir?",
  ui_story_30110601_81_dialog_content = "Sharona! Sharona!!",
  ui_story_30110601_82_dialog_content = "Kalau kamu bisa mendengarku, tolong katakan sesuatu!",
  ui_story_30110601_83_dialog_content = "Sharo—",
  ui_story_30110601_84_dialog_content = "Aku di sini, Caelestite.",
  ui_story_30110601_85_dialog_content = "Woah...",
  ui_story_30110601_86_dialog_content = "Tempat apa ini, Sharona? Apakah itu...?",
  ui_story_30110601_87_dialog_content = "...",
  ui_story_30110601_88_dialog_content = "Tidak ada yang perlu disebutkan. Ini hanyalah mural, tidak lebih.",
  ui_story_30110601_89_dialog_content = "Muralnya cantik... tidak, mengejutkan!",
  ui_story_30110601_90_dialog_content = "Aku tidak bisa menjelaskannya, tetapi aku mulai merinding.",
  ui_story_30110601_91_dialog_content = "Kau terluka?",
  ui_story_30110601_92_dialog_content = "Tidak.",
  ui_story_30110601_93_dialog_content = "Bagus.",
  ui_story_30110601_94_dialog_content = "Sharona... Tempat apa ini?",
  ui_story_30110601_95_dialog_content = "Orang-orang di mural ini... Pakaian mereka terlihat agak familier.",
  ui_story_30110601_96_dialog_content = "Mereka melakukannya, bukan?",
  ui_story_30110601_97_dialog_content = "Mereka berasal dari Lumopolis.",
  ui_story_30110601_98_dialog_content = "Lumopolis?! Namun, bukankah kamu selalu...",
  ui_story_30110601_99_dialog_content = "Menentang cara lama Lumopolis yang keras kepala?",
  ui_story_30110601_100_dialog_content = "Jika begitu, kenapa kamu memilih untuk datang ke sini? Tempat ini... jika aku tidak salah, ini adalah pemakaman untuk bangsawan Lumopolis.",
  ui_story_30110601_101_dialog_content = "...",
  ui_story_30110601_102_dialog_content = "Sejujurnya, tadinya kupikir kamu sudah menggunakan kekuatanmu untuk mencari tahu kebenaran sampai sekarang, Caelestite.",
  ui_story_30110601_103_dialog_content = "Ini adalah tempat peristirahatan terakhir <color=#FFB400>klanku</color>.",
  ui_story_30110601_104_dialog_content = "Tanah di bawah kakimu telah dibuahi oleh darah dan tulang para bangsawan <color=#FFB400>Kartima</color> Family.",
  ui_story_30110601_105_dialog_content = "Mereka seharusnya dikebumikan di kerajaan surgawi Demi White Night...",
  ui_story_30110601_106_dialog_content = "Namun, sayangnya, karena insiden itu...",
  ui_story_30110601_107_dialog_content = "Perebutan kekuasaan yang kekurangan dokumentasi yang tepat, dan dipenuhi dengan catatan palsu.",
  ui_story_30110601_108_dialog_content = "Kartima Family dicap sebagai pengkhianat sejak itu.",
  ui_story_30110601_109_dialog_content = "Anggota yang masih hidup diasingkan, dan yang telah tiada bahkan tidak bisa beristirahat dalam damai.",
  ui_story_30110601_110_dialog_content = "Mereka bahkan tidak mendapatkan ampunan untuk dikebumikan di pemakaman mereka sendiri. Yang bisa mereka lakukan hanyalah memohon kepada keluarga yang lebih simpatik untuk membantu mereka secara rahasia...",
  ui_story_30110601_111_dialog_content = "...Dan jadi, mereka diletakkan untuk beristirahat di sini.",
  ui_story_30110601_112_dialog_content = "Sungguh ironis...",
  ui_story_30110601_113_dialog_content = "Nenek moyang Keluarga Kartima telah mengorbankan darah dan nyawa mereka untuk melindungi Lumopolis, tetapi sekarang... Mereka hampir seluruhnya dilupakan oleh orang-orang.",
  ui_story_30110601_114_dialog_content = "Kekaisaran telah lupa bahwa kejayaannya saat ini dibangun atas darah naga.",
  ui_story_30110601_115_dialog_content = "Demi White Night...",
  ui_story_30110601_116_dialog_content = "Namun, darah dan tulang di bawahnya.",
  ui_story_30110601_117_dialog_content = "Aku turut sedih...",
  ui_story_30110601_118_dialog_content = "Aku tidak bermaksud untuk mengungkit...",
  ui_story_30110601_119_dialog_content = "Terimalah permintaan maafku, Sharona... Kamu dan keluargamu.",
  ui_story_30110601_120_dialog_content = "Sebagai orang luar, aku telah mengganggu tidur mereka.",
  ui_story_30110601_121_dialog_content = "...",
  ui_story_30110601_122_dialog_content = "Mereka bukan keluargaku.",
  ui_story_30110601_123_dialog_content = "Namun, namamu...",
  ui_story_30110601_124_dialog_content = "Kamu benar-benar berpikir kami adalah keluarga hanya karena kami memiliki nama keluarga yang sama?",
  ui_story_30110601_125_dialog_content = "Sharona Kartima...",
  ui_story_30110601_126_dialog_content = "Mereka adalah klanku, tetapi mereka bukan keluargaku.",
  ui_story_30110601_127_dialog_content = "Mereka tidak punya cara untuk mengungkapkan kebenaran tentang kematian orang tuaku, dan aku juga tidak bisa berpura-pura bahwa aku tidak memiliki ikatan dengan mereka.",
  ui_story_30110601_128_dialog_content = "Orang tuamu...",
  ui_story_30110601_129_dialog_content = "Aku bahkan tidak mengingat mereka lagi.",
  ui_story_30110601_130_dialog_content = "Dalam hal Kartima Family, hal yang meninggalkan kesan terdalam padaku...",
  ui_story_30110601_131_dialog_content = "Terjadi pada hari <color=#FFB400>genosida</color>.",
  ui_story_30110601_132_dialog_content = "Tepat sebelum meninggal, seorang tetua yang dihormati di keluarga memberitahuku...",
  ui_story_30110601_133_dialog_content = "Untuk selalu mengingat namaku, dan tidak pernah menyerah untuk mencari <color=#FFB400>rahasia</color> dari garis keturunanku.",
  ui_story_30110601_134_dialog_content = "Sebelum itu, saya bahkan tidak pantas untuk menyapa pria itu di pertemuan keluarga.",
  ui_story_30110601_135_dialog_content = "Kalau begitu... apakah kamu sudah menemukan rahasia garis keturunanmu?",
  ui_story_30110601_136_dialog_content = "Aku telah lama mencarinya, tetapi... Aku masih belum menemukan jawabannya.",
  ui_story_30110601_137_dialog_content = "Aku bahkan tidak tahu kenapa aku dipercayakan dengan tugas yang mustahil ini sejak awal.",
  ui_story_30110601_138_dialog_content = "Hanya karena aku anggota terakhir yang bertahan dari keluarga kami, aku diharapkan untuk memikul beban sejarah rahasia garis keturunan kami?",
  ui_story_30110601_139_dialog_content = "Serpihan masa lalu terus-menerus muncul di benakku dan menghadirkan aliran kebencian yang tiada hentinya...",
  ui_story_30110601_140_dialog_content = "...Ini tidak adil.",
  ui_story_30110601_141_dialog_content = "Maafkan aku...",
  ui_story_30110601_142_dialog_content = "Aku sungguh tidak bermaksud menanyakan tentang kamu dan masa lalu klanmu...",
  ui_story_30110601_143_dialog_content = "Andai kamu tidak membawaku ke sini, kamu tidak akan pernah tahu.",
  ui_story_30110601_144_dialog_content = "Ya...",
  ui_story_30110601_145_dialog_content = "Tunggu... Keluarga! Benar sekali!",
  ui_story_30110601_146_dialog_content = "Illumina! Illumina Federation!",
  ui_story_30110601_147_option_content = "Mereka rumahmu yang sebenarnya, 'kan, Sharona?",
  ui_story_30110601_148_dialog_content = "...Rumahku?",
  ui_story_30110601_149_dialog_content = "Rumah adalah tempat yang mencintai saya tanpa syarat dan tidak meminta apa-apa sebagai balasan.",
  ui_story_30110601_150_dialog_content = "Hubunganku dengan Illumina... Dibangun berlandaskan kepercayaan dari Grand Marshal.",
  ui_story_30110601_151_option_content = "Tidak, Illumina juga tidak masuk hitungan...",
  ui_story_30110601_152_dialog_content = "Aku setuju, untuk sebagian besarnya.",
  ui_story_30110601_153_dialog_content = "Arti dari rumah jauh lebih dalam.",
  ui_story_30110601_154_dialog_content = "Sebuah rumah menyediakan rasa cinta yang dalam dan tak terpisahkan...",
  ui_story_30110601_155_dialog_content = "Sementara di Illumina, aku bekerja hanya untuk memenuhi kepercayaan dan harapan orang lain.",
  ui_story_30110601_156_dialog_content = "Meski begitu, sebagai balasannya, aku mendapatkan kekuatan yang cukup besar...",
  ui_story_30110601_157_dialog_content = "Kadang, aku berpikir... Mungkin tempat ini adalah rumahku.",
  ui_story_30110601_158_dialog_content = "(Sebenarnya arti dari rumah itu apa...?)",
  ui_story_30110601_159_dialog_content = "(Aku sendiri belum pernah tinggal di Eraveil, tetapi...)",
  ui_story_30110601_160_dialog_content = "(Aku bisa bilang dengan yakin, Eraveil adalah rumahku.)",
  ui_story_30110601_161_dialog_content = "(Lalu, Soroz... Dia bukan hanya tempatku bernaung, melainkan juga temanku. Aku tidak pernah benar-benar sendirian saat masih kecil...)",
  ui_story_30110601_162_dialog_content = "(Dan sejak itu, aku telah membuat berbagai jenis teman.)",
  ui_story_30110601_163_dialog_content = "(Namun, untuk Sharona... Di manakah rumahnya?)",
  ui_story_30110601_164_dialog_content = "(Meski tidak pernah mengenal kerabatku, aku yakin kasih sayang mereka kepadaku itu nyata.)",
  ui_story_30110601_165_dialog_content = "(Sharona tumbuh dikelilingi oleh keluarga, tetapi masih tidak tahu di mana rumahnya...)",
  ui_story_30110601_166_dialog_content = "Aku sudah terlalu banyak bicara.",
  ui_story_30110601_167_dialog_content = "Terima kasih atas bantuanmu, Caelestite.",
  ui_story_30110601_168_dialog_content = "B-bukan masalah.",
  ui_story_30110601_169_dialog_content = "Aku yakin semua ini pasti membuatmu bingung.",
  ui_story_30110601_170_dialog_content = "Lagi pula, untuk apa aku ada di sini memberi hormat jika mereka bukan keluargaku?",
  ui_story_30110601_171_dialog_content = "Kurasa... Kamu mencoba memahami apa yang terjadi pada masa lalu, 'kan?",
  ui_story_30110601_172_option_content = "Kebenaran di balik klanmu?",
  ui_story_30110601_173_dialog_content = "Ya.",
  ui_story_30110601_174_dialog_content = "Serta hubungan kami dengan naga.",
  ui_story_30110601_175_dialog_content = "Serpihan teriakan dari ingatanku... tentang naga sejati.",
  ui_story_30110601_176_option_content = "Rahasia garis keturunanmu?",
  ui_story_30110601_177_dialog_content = "Ya.",
  ui_story_30110601_178_dialog_content = "Mungkin setelah aku mengungkap rahasia Kartima Family...",
  ui_story_30110601_179_dialog_content = "Kebenaran di balik masa lalu, dan jawaban atas serpihan rasa benci dalam benakku... Mungkin saat itulah semua akan terungkap.",
  ui_story_30110601_180_dialog_content = "Namun, hingga aku menemukan kebenaran di balik itu semua...",
  ui_story_30110601_181_dialog_content = "Yang bisa kulakukan hanyalah datang kemari untuk memberikan penghormatan setiap tahun, dengan harapan bisa merasakan sesuatu...",
  ui_story_30110601_182_dialog_content = "Karena kami memiliki nama keluarga yang sama, aku tidak pernah benar-benar sendirian.",
  ui_story_30110601_183_dialog_content = "Meski... Aku tidak menganggap mereka sebagai keluargaku.",
  ui_story_30110601_184_dialog_content = "(Keluarga...)",
  ui_story_30110601_185_dialog_content = "Aku...",
  ui_story_30110601_186_dialog_content = "Sharona... Tolong sampaikan rasa hormatku kepada mereka.",
  ui_story_30110601_187_dialog_content = "Ayo pergi.",
  ui_story_30110601_188_dialog_content = "Sebelum kita pergi... Ada sesuatu yang harus aku minta darimu.",
  ui_story_30110601_189_dialog_content = "Tentu.",
  ui_story_30110601_190_dialog_content = "Caelestite... Aku meminta kamu untuk tidak memberitahukan lokasi tempat ini kepada siapa pun.",
  ui_story_30110601_191_dialog_content = "Sejauh pemahamanku tentang orang-orang Lumopolis...",
  ui_story_30110601_192_dialog_content = "Mereka cepat melupakan kebaikan, tetapi tidak akan pernah melupakan dendam.",
  ui_story_30110601_193_dialog_content = "Terutama dendam terhadap pengkhianat, Kartima Family...",
  ui_story_30110601_194_dialog_content = "Kebencian mereka takkan pernah benar-benar lenyap.",
  ui_story_30110601_195_dialog_content = "Aku khawatir ini adalah satu-satunya kesamaan yang kumiliki dengan orang-orang Lumopolis.",
  ui_story_30110601_196_dialog_content = "Itu selalu ada... Rasa benci yang tidak asing, senantiasa membuat darahku mendidih...",
  ui_story_30110601_197_dialog_content = "Aku berjanji.",
  ui_story_30110601_198_dialog_content = "Sungguh momen yang menyentuh...",
  ui_story_30110601_199_dialog_content = "Jika benar-benar begitu menyentuh, lalu kenapa kamu tidak menangis?",
  ui_story_30110601_200_dialog_content = "Menangis? Untuk apa aku menangis?",
  ui_story_30110601_201_dialog_content = "Jangan membuatku tertawa.",
  ui_story_30110601_202_dialog_content = "...Kamu terlambat, Leona.",
  ui_story_30110601_203_dialog_content = "Terlambat? Mereka tidak layak dikunjungi, apalagi aku harus tepat waktu.",
  ui_story_30110601_204_dialog_content = "Pakaianmu...",
  ui_story_30110601_205_dialog_content = "Masih mencoba mengikuti <color=#FFB400>tradisi</color> mereka yang sudah lama mati, Sharona?",
  ui_story_30110601_206_dialog_content = "Tidak ada seorang pun di dunia ini selain saya yang mengenali pakaian itu sebagai pakaian resmi Kartima Family.",
  ui_story_30110601_207_dialog_content = "Lalu, selama kita masih hidup, dan aku memiliki pakaian ini...",
  ui_story_30110601_208_dialog_content = "Kartima Family belum benar-benar terhapus dari sejarah.",
  ui_story_30110601_209_dialog_content = "Huh... Betapa naif.",
  ui_story_30110601_210_dialog_content = "Apa gunanya formalitas dan penghormatan ini jika kita dikutuk untuk mengulangi kesalahan yang sama?",
  ui_story_30110601_211_dialog_content = "Namun, kamu sudah sangat memahaminya, 'kan... Dik?",
  ui_story_30110601_212_dialog_content = "Tidak ada yang bisa lari dari takdir ini. Kelak, kita juga akan terbaring kaku dan mati di tempat ini.",
  ui_story_30110601_213_dialog_content = "Satu-satunya perbedaan adalah, saat kita tiada, tidak ada seorang pun di sana yang akan mengenakan pakaian itu dan memberikan penghormatan kepada kita.",
  ui_story_30110601_214_dialog_content = "...Bukan masalah.",
  ui_story_30110601_215_dialog_content = "Oh, Dik... pemahamanmu tentang takdir sungguhlah dangkal.",
  ui_story_30110601_216_dialog_content = "Namun, aku pikir...",
  ui_story_30110601_217_dialog_content = "Ada seseorang di sini yang lebih memahami takdir...",
  ui_story_30110601_218_dialog_content = "Bukankah begitu... Si Caelestite yang kesepian?",
  ui_story_30110601_219_dialog_content = "...Aku?",
  ui_story_30110601_220_dialog_content = "Aku sama sekali tidak sendirian!",
  ui_story_30110601_221_dialog_content = "Benarkah itu, Nak? Aku iri dengan rasa percaya dirimu.",
  ui_story_30110601_222_dialog_content = "Aku hanya berharap kamu tidak pernah berhenti merasa seperti itu...",
  ui_story_30110601_223_dialog_content = "Sekarang, Sayangku. Aku harus mengucapkan selamat tinggal.",
  ui_story_30110601_224_dialog_content = "Dia masuk ke dalam, Sharona...",
  ui_story_30110601_225_dialog_content = "...",
  ui_story_30110601_226_dialog_content = "Sharona? Sharona!",
  ui_story_30110601_227_dialog_content = "...Ayo kita pergi.",
  ui_story_30110601_228_dialog_content = "Kembali ke... Illumina.",
  ui_story_30110601_229_dialog_content = "...Tentu. Mari kita kembali bersama.",
  ui_story_30110601_230_dialog_content = "<color=#e8d9bb>Keesokan harinya.</color>",
  ui_story_30110601_231_dialog_content = "Navigator? Hei, Navigator! Kamu baik-baik saja?",
  ui_story_30110601_232_dialog_content = "Eh... Hah?",
  ui_story_30110601_233_dialog_content = "Kamu sedang memikirkan apa? Butuh udara segar? Ayo, kita pergi jalan-jalan keliling Gannon City!",
  ui_story_30110601_234_dialog_content = "A-aku sedang tidak memikirkan apa pun, sungguh...",
  ui_story_30110601_235_dialog_content = "Hei, Vice... apa arti kata rumah bagimu?",
  ui_story_30110601_236_dialog_content = "Hah? Jika aku harus mengatakannya...",
  ui_story_30110601_237_dialog_content = "Colossus adalah rumahku, begitu juga Illumina.",
  ui_story_30110601_238_dialog_content = "Di mana pun aku bisa hidup dengan nyaman adalah tempat yang bisa kusebut rumah.",
  ui_story_30110601_239_dialog_content = "Ya...",
  ui_story_30110601_240_dialog_content = "Tempat yang nyaman...",
  ui_story_30110601_241_dialog_content = "(Bagi Sharona, rumah adalah tempat dia selalu bisa kembali. Itu adalah tempat dia berada.",
  ui_story_30110601_242_dialog_content = "(Mengabdikan dirinya untuk Illumina...)",
  ui_story_30110601_243_dialog_content = "(Adalah caranya menentang takdir dan menemukan rumah.)",
  ui_story_30110601_244_dialog_content = "(Aku ingin tahu...)",
  ui_story_30110601_245_dialog_content = "(Apakah Colossus akan dianggap sebagai rumah baginya?)",
  ui_story_30110602_1_dialog_content = "Menurut koordinat, ini seharusnya tempatnya. Tapi...",
  ui_story_30110602_2_dialog_content = "Apakah Sharona benar-benar terlambat?",
  ui_story_30110602_3_dialog_content = "Meskipun begitu, seharusnya sebagian besar pasukan Illumina sudah ada di sini sekarang...",
  ui_story_30110602_4_dialog_content = "Seharusnya tidak sepi seperti ini di sini.",
  ui_story_30110602_5_dialog_content = "Bisa jadi... Apakah aku salah menentukan lokasi?",
  ui_story_30110602_6_dialog_content = "Jika aku terlambat karena kesalahan bodoh seperti itu, Sharona pasti akan marah. Sebaiknya aku...",
  ui_story_30110602_7_dialog_content = "Tidak, kamu berada di tempat yang benar, PlayerName.",
  ui_story_30110602_8_dialog_content = "!",
  ui_story_30110602_9_dialog_content = "Commander Sharona? Hampir saja aku tidak mengenali kamu! Jadi kamu ada di sini sejak awal...",
  ui_story_30110602_10_dialog_content = "Kamu, eh...",
  ui_story_30110602_11_dialog_content = "Berhenti berbasa-basi. Jika ada pertanyaan, tanya saja langsung padaku.",
  ui_story_30110602_12_dialog_content = "Kenapa kamu sendirian? Di mana sisa dari Illumina Legion? Dan... Apa itu pakaianmu?",
  ui_story_30110602_13_dialog_content = "Aku akan menjawab pertanyaanmu satu per satu.",
  ui_story_30110602_14_dialog_content = "Pertama, ini adalah misi pribadi, satu yang tidak melibatkan militer Federasi Illumina.",
  ui_story_30110602_15_dialog_content = "Kedua, saya menyiapkan pakaian ini khusus untuk misi ini.",
  ui_story_30110602_16_dialog_content = "Pakaian khusus untuk misi pribadi, huh? Yah, mereka terlihat sangat mahal.",
  ui_story_30110602_17_dialog_content = "Sebenarnya, mereka tampak sedikit tidak pada tempatnya di sini.",
  ui_story_30110602_18_dialog_content = "Apakah mereka memiliki hubungan dengan reruntuhan putih ini?",
  ui_story_30110602_19_dialog_content = "Sangat tanggap, PlayerName.",
  ui_story_30110602_20_dialog_content = "Baru-baru ini saya menemukan sekelompok orang yang tampak mencurigakan. Mereka secara rutin menyembah patung naga di dekat sana.",
  ui_story_30110602_21_dialog_content = "Saya menduga mereka kemungkinan besar adalah sekelompok penyembah setan... atau sisa-sisa dari faksi pengkhianat.",
  ui_story_30110602_22_dialog_content = "Apa itu berarti...",
  ui_story_30110602_23_dialog_content = "Saya curiga mereka memiliki hubungan dengan Rumah Kartima dalam beberapa cara, ya.",
  ui_story_30110602_24_dialog_content = "Jadi, pakaian ini milik Rumah Kartima?",
  ui_story_30110602_25_dialog_content = "Sama sekali tidak. Ini hanyalah penyamaran yang digunakan untuk menyusup ke jajaran mereka.",
  ui_story_30110602_26_dialog_content = "Aku memilih pakaian ini untuk cocok dengan yang aku lihat mereka pakai saat ibadah mereka.",
  ui_story_30110602_27_dialog_content = "Benarkah? Tapi sepertinya mereka dibuat khusus untukmu.",
  ui_story_30110602_28_dialog_content = "Dengan pakaian seputih dan semulia ini, mereka mungkin bahkan akan mengira kamu adalah seorang santo atau semacamnya.",
  ui_story_30110602_29_dialog_content = "Itu tidak penting sekarang, PlayerName.",
  ui_story_30110602_30_dialog_content = "Yang penting adalah aku bisa menggunakan penyamaran ini untuk menyusup dan mengalahkan mereka.",
  ui_story_30110602_31_dialog_content = "Lokasi ini sudah dibersihkan dari tanda-tanda pertempuran, itulah sebabnya saya mengundang Anda ke sini.",
  ui_story_30110602_32_dialog_content = "Seseorang yang mahir dalam sejarah kuno seperti kamu seharusnya bisa mengetahui apakah reruntuhan ini terkait dengan Rumah Kartima atau naga, bukan?",
  ui_story_30110602_33_dialog_content = "Tentu, aku akan mencoba yang terbaik.",
  ui_story_30110602_34_dialog_content = "Tapi... Bukankah lebih mudah untuk bertanya langsung pada orang-orang yang kalian tangkap?",
  ui_story_30110602_35_dialog_content = "... Saya mencoba, tetapi hanya satu dari mereka yang masih sadar setelah pertempuran, dan dia langsung pingsan begitu saya mulai menanyainya.",
  ui_story_30110602_36_dialog_content = "Tidak mengherankan sama sekali... Aku bisa membayangkan pertempuran itu dalam pikiranku...",
  ui_story_30110602_37_dialog_content = "Juga, mereka terus mengeluarkan omong kosong selama pertarungan kita. Sesuatu mengatakan kepada saya bahwa saya tidak akan mendapatkan apa pun yang berguna dari mereka dalam waktu dekat.",
  ui_story_30110602_38_dialog_content = "Itulah sebabnya aku memutuskan untuk meminta bantuanmu.",
  ui_story_30110602_39_dialog_content = "Aku mengerti. Jangan khawatir, aku bisa menanganinya.",
  ui_story_30110602_40_dialog_content = "<color=#e8d9bb>Setelah beberapa saat...</color>",
  ui_story_30110602_41_dialog_content = "Fiuh... Saya pikir saya sudah memahami sebagian besar sekarang.",
  ui_story_30110602_42_dialog_content = "Jawabannya mungkin sedikit mengecewakan. Tempat ini tidak ada hubungannya dengan House Kartima.",
  ui_story_30110602_43_dialog_content = "... Begitukah?",
  ui_story_30110602_44_dialog_content = "Lalu mengapa mereka beribadah di sini?",
  ui_story_30110602_45_dialog_content = "Mereka tampaknya sedang berdoa kepada kekuatan yang lebih jahat. Berdasarkan bukti-bukti yang ada di sekitar sini...",
  ui_story_30110602_46_dialog_content = "Mungkin mereka melihat idol naga sebagai semacam Eclipsite yang kuat.",
  ui_story_30110602_47_dialog_content = "Lagi pula, tidak banyak orang yang telah melihat naga asli saat ini.",
  ui_story_30110602_48_dialog_content = "Saya mengerti. Seharusnya saya tahu lebih baik daripada berharap terlalu banyak.",
  ui_story_30110602_49_dialog_content = "Pria yang pernah saya sebutkan sebelumnya, orang yang pingsan karena ketakutan saat saya tanya... Ada alasan untuk itu.",
  ui_story_30110602_50_dialog_content = "Selama pertempuran kami tadi...",
  ui_story_30110602_51_dialog_content = "Apa yang terjadi?",
  ui_story_30110602_52_dialog_content = "Aku terlalu bersemangat dan hampir kehilangan akal sehatku.",
  ui_story_30110602_53_dialog_content = "Kemungkinan mereka memiliki hubungan dengan keluarga saya dan pemberontakan membuat saya tidak bisa mengendalikan emosi saya.",
  ui_story_30110602_54_dialog_content = "Teriakan mereka penuh dengan ketakutan saat mereka berusaha mati-matian menjauhkan saya...",
  ui_story_30110602_55_dialog_content = "Sejujurnya, saya membenci bagian diri saya itu.",
  ui_story_30110602_56_dialog_content = "Tapi kamu berhasil mengambil alih kendali pada akhirnya, bukan?",
  ui_story_30110602_57_dialog_content = "Saya memang melakukannya, tapi dengan sangat terpaksa. Kenyataannya adalah—",
  ui_story_30110602_58_dialog_content = "Saya hanya mendapatkan kembali kontrol karena saya pikir kamu mungkin bisa memberi saya lebih banyak jawaban, PlayerName.",
  ui_story_30110602_59_dialog_content = "Tapi kebencianku terhadap Lumopolis dan keluargaku... serta kekuatanku sendiri—",
  ui_story_30110602_60_dialog_content = "Mungkin akan ada hari ketika itu membuat saya benar-benar kehilangan kendali.",
  ui_story_30110602_61_dialog_content = "Mungkin saja jiwa saya sudah lama menyerah pada kekerasan.",
  ui_story_30110602_62_dialog_content = "Andai saja aku bisa tahu bagaimana perasaan nenek moyangku tentang kekuatan ini.",
  ui_story_30110602_63_dialog_content = "(Jadi itulah mengapa dia ingin tahu apakah reruntuhan ini ada hubungannya dengan keluarganya...)",
  ui_story_30110602_64_dialog_content = "Nah... Dari apa yang saya dengar, kamu benar-benar berhasil menumbangkan sekelompok penyembah setan yang jahat.",
  ui_story_30110602_65_dialog_content = "Jika kamu tidak menghentikan mereka, siapa tahu apa jenis masalah yang akan mereka sebabkan.",
  ui_story_30110602_66_dialog_content = "Itu adalah kemenangan besar menurutku. Kamu setuju, bukan?",
  ui_story_30110602_67_dialog_content = "Tapi saya hanya melakukannya murni karena kepentingan diri sendiri.",
  ui_story_30110602_68_dialog_content = "Saya tidak akan sampai sejauh itu, Sharona.",
  ui_story_30110602_69_dialog_content = "Jika Anda benar-benar hanya tertarik untuk mempelajari hubungan mereka dengan House Kartima, Anda bisa dengan mudah menghindari pertarungan dengan mereka.",
  ui_story_30110602_70_dialog_content = "Tapi kamu melihat kelompok mereka sebagai ancaman bagi Illumina dan yang lainnya, jadi kamu bertindak tegas dan berhasil menjatuhkan mereka.",
  ui_story_30110602_71_dialog_content = "Di akhir hari, kamu masih ingin menggunakan kekuatanmu untuk melindungi orang lain, bukan?",
  ui_story_30110602_72_dialog_content = "Tapi... Bisakah kekuatan penghancur seperti milikku benar-benar digunakan untuk melindungi orang-orang?",
  ui_story_30110602_73_dialog_content = "Bisa! Fakta bahwa House Kartima masih ada setelah semua ini adalah bukti dari hal tersebut.",
  ui_story_30110602_74_dialog_content = "Saya yakin leluhurmu juga menggunakan kekuatan mereka untuk melindungi orang-orang yang penting bagi mereka di masa lalu.",
  ui_story_30110602_75_dialog_content = "Saya juga yakin bahwa kamu telah mewarisi tugas mereka, dan akan menggunakan kekuatanmu sendiri untuk melindungi Illumina dan orang-orang yang kamu pedulikan.",
  ui_story_30110602_76_dialog_content = "Apakah saya benar-benar memiliki hak untuk melakukan itu?",
  ui_story_30110602_77_dialog_content = "Tentu saja kamu bisa, Sharona! Aku telah melihat betapa kuatnya kamu, tapi aku juga telah melihat betapa baiknya kamu.",
  ui_story_30110602_78_dialog_content = "Jika ada yang bisa melakukan ini, itu adalah kamu!",
  ui_story_30110602_79_dialog_content = "...",
  ui_story_30110602_80_dialog_content = "Terima kasih, PlayerName. Saya selalu berterima kasih atas bimbingan tanpa henti dari Anda.",
  ui_story_30110602_81_dialog_content = "Terkadang saya bertanya-tanya bagaimana hidup saya jika saya memiliki seseorang seperti Anda dalam keluarga saya.",
  ui_story_30110602_82_dialog_content = "Apakah saya akan menjadi begitu buas jika itu terjadi?",
  ui_story_30110602_83_dialog_content = "Keluarga...",
  ui_story_30110602_84_dialog_content = "(Sharona pernah mengatakan sesuatu tentang ini sebelumnya...)",
  ui_story_30110602_85_dialog_content = "Rumah adalah tempat yang mencintai saya tanpa syarat dan tidak meminta apa-apa sebagai balasan.",
  ui_story_30110602_86_dialog_content = "(Jika dia tidak benar-benar melihat Illumina sebagai tempat yang bisa dia sebut rumah, maka...)",
  ui_story_30110602_87_option_content = "Mengapa tidak menjadikan Colossus sebagai rumahmu?",
  ui_story_30110602_88_dialog_content = "Colossus? Yah, memang ada perasaan seperti di rumah.",
  ui_story_30110602_89_dialog_content = "Kamu dan teman-temanmu semua tinggal di sana, dan semua orang tampaknya melihatnya sebagai tempat di mana mereka selalu diterima.",
  ui_story_30110602_90_dialog_content = "Tapi... Maafkan ketidakbijaksanaanku dan lupakan apapun yang telah aku katakan tentang hal itu.",
  ui_story_30110602_91_option_content = "Ingin saya menjadi bagian dari keluarga Anda?",
  ui_story_30110602_92_dialog_content = "Ah... Maaf, PlayerName, saya hanya berbicara sendiri barusan.",
  ui_story_30110602_93_dialog_content = "Mohon maafkan aku karena mengungkapkan pikiran-pikiran tak berguna itu dan membuatmu khawatir.",
  ui_story_30110602_94_dialog_content = "Coba jangan terlalu memikirkannya. Itu hanya keluhan spontan.",
  ui_story_30110602_95_dialog_content = "Saya sedang serius.",
  ui_story_30110602_96_dialog_content = "Kamu tadi?",
  ui_story_30110602_97_dialog_content = "Tentu saja. Aku tidak akan berani membuat lelucon di depan patung naga, setelah semua.",
  ui_story_30110602_98_dialog_content = "Kamu pernah bilang padaku bahwa Illumina bukanlah rumahmu yang sebenarnya... Jika kamu pernah tertarik, menurutku Colossus adalah pilihan yang bagus!",
  ui_story_30110602_99_dialog_content = "Kamu selalu menjagaku, jadi saya ingin melakukan segala yang bisa saya lakukan untuk membantumu juga.",
  ui_story_30110602_100_dialog_content = "Mungkin sedikit sombong jika saya mengatakannya, tapi saya benar-benar berharap saya bisa menjadi seseorang yang bisa Anda andalkan.",
  ui_story_30110602_101_dialog_content = "Setelah semua, kau bilang kau memikirkan aku tepat sebelum kau kehilangan kendali tadi, benar?",
  ui_story_30110602_102_dialog_content = "Jika memikirkan tentang saya membantu, maka mungkin suatu hari nanti kamu akan bisa mengubah kekuatan penghancuranmu—",
  ui_story_30110602_103_dialog_content = "—menjadi kekuatan untuk melindungi sesuatu yang penting?",
  ui_story_30110602_104_dialog_content = "Sesuatu yang penting...",
  ui_story_30110602_105_dialog_content = "Saya tidak bisa menyangkal bahwa Anda sempat terlintas dalam pikiran saya sebelumnya, PlayerName.",
  ui_story_30110602_106_dialog_content = "Namun…",
  ui_story_30110602_107_dialog_content = "Ah, tapi kamu tidak perlu membuat keputusan sekarang juga atau apapun itu!",
  ui_story_30110602_108_dialog_content = "Meskipun mungkin terkesan kurang ajar jika aku meminta, aku benar-benar berharap kamu akan mempertimbangkannya, Sharona.",
  ui_story_30110602_109_dialog_content = "Tolong jangan salah paham, saya tidak bermaksud membuatmu marah.",
  ui_story_30110602_110_dialog_content = "Tapi pikiran tentang kamu menjadi bagian dari keluarga saya...",
  ui_story_30110602_111_dialog_content = "Aku tidak yakin bisa menerima itu... setidaknya tidak dengan keadaanku sekarang.",
  ui_story_30110602_112_dialog_content = "Mungkin aku butuh lebih banyak waktu untuk bersiap.",
  ui_story_30110602_113_dialog_content = "Ambil semua waktu yang kamu butuhkan! Saat punya waktu luang, kenapa tidak mampir dan kunjungi rumah baru potensialmu?",
  ui_story_30110602_114_dialog_content = "Saya selalu terbuka untuk saran, terutama jika itu membuat Colossus terasa lebih seperti rumah bagi Anda.",
  ui_story_30110602_115_dialog_content = "Tidak usah.",
  ui_story_30110602_116_dialog_content = "Tidak ada bedanya bagi saya apakah saya berada di Illumina atau di atas Colossus.",
  ui_story_30110602_117_dialog_content = "<size=30>Selama aku di sisimu...</size>",
  ui_story_30110602_118_dialog_content = "Apa katamu?",
  ui_story_30110602_119_dialog_content = "Oh, tidak ada apa-apa. Aku hanya... bicara pada diri sendiri lagi.",
  ui_story_30110602_120_dialog_content = "Kebetulan aku punya waktu luang hari ini, karena aku mengambil cuti hari ini untuk misi pribadi ini.",
  ui_story_30110602_121_dialog_content = "Apakah kamu keberatan jika saya menghabiskan hari bersamamu di Colossus?",
  ui_story_30110602_122_dialog_content = "Tentu saja tidak! Anda selalu dipersilakan untuk bergabung!",
  ui_story_30110602_123_dialog_content = "Jika kamu benar-benar ingin menjadi bagian dari keluargaku, PlayerName...",
  ui_story_30110602_124_dialog_content = "Kamu juga harus melakukan banyak persiapan dalam hidupmu. Saya harap kamu siap untuk ini.",
  ui_story_30110602_125_dialog_content = "Anu…",
  ui_story_30110602_126_dialog_content = "Apa masalahnya? Sudah merasa menyesal?",
  ui_story_30110602_127_dialog_content = "S-S-Sama sekali tidak! Saya siap melakukan apa pun yang diperlukan untuk layak menjadi keluarga Anda!"
}
return config
